  metadata jsonb default '{}'::jsonb,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null
);

create table if not exists public.tennis_predictions (
  id uuid default gen_random_uuid() not null,
  fixture_id uuid not null,
  market text not null,
  prediction text not null,
  probability numeric(5,4) not null,
  confidence_category text not null,
  secondary_predictions jsonb default '[]'::jsonb,
  simulations_count integer default 250000 not null,
  tier_required text default 'free'::text not null,
  publication_status text default 'published'::text not null,
  target_kickoff_at timestamp with time zone not null,
  metadata jsonb default '{}'::jsonb,
  settlement_status text default 'pending'::text not null,
  settlement_notes text,
  settled_at timestamp with time zone,
  actual_result text,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null
);

create table if not exists public.tennis_settlements (
  id uuid default gen_random_uuid() not null,
  prediction_id uuid not null,
  fixture_id uuid not null,
  status text not null,
  p1_sets integer default 0,
  p2_sets integer default 0,
  total_games integer default 0,
  was_retired boolean default false not null,
  was_walkover boolean default false not null,
  settlement_logic_version text default '1.0'::text not null,
  notes text,
  settled_at timestamp with time zone default now() not null,
  created_at timestamp with time zone default now() not null
);

create table if not exists public.tennis_tournaments (
  id uuid default gen_random_uuid() not null,
  name text not null,
  tour text not null,
  category text not null,
  surface text not null,
  court_pace_index numeric(4,1) default 35.0,
  country text,
  city text,
  is_active boolean default true not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null
);

create table if not exists public.user_preferences (
  user_id uuid not null,
  odds_format text default 'decimal'::text not null,
  default_stake numeric(10,2) default 10.00,
  preferred_leagues jsonb default '[]'::jsonb,
  updated_at timestamp with time zone default now() not null
);

create table if not exists public.users (
  id uuid default gen_random_uuid() not null,
  email text not null,
  role text default 'user'::text not null,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  disclaimer_age_accepted boolean default false not null,
  disclaimer_age_accepted_at timestamp with time zone,
  disclaimer_financial_accepted boolean default false not null,
  disclaimer_financial_accepted_at timestamp with time zone,
  disclaimer_version text default 'v1.0'::text,
  display_name text,
  is_deleted boolean default false not null,
  status text default 'active'::text not null,
  deleted_at timestamp with time zone,
  telegram_chat_id text,
  telegram_username text,
  telegram_auth_token text,
  telegram_auth_expires_at timestamp with time zone,
  whatsapp_phone text
);

create table if not exists public.value_bets (
  id uuid default gen_random_uuid() not null,
  fixture_id uuid not null,
  market_type text not null,
  selection text not null,
  bookmaker text not null,
  bookmaker_odds numeric(8,3) not null,
  model_probability numeric(5,4) not null,
  edge_percentage numeric(6,3) not null,
  kelly_recommendation numeric(5,4),
  status text default 'active'::text not null,
  created_at timestamp with time zone default now() not null
);

create table if not exists public.webhook_events_log (
  event_id text not null,
  event_type text not null,
  provider text default 'bachs'::text not null,
  payload jsonb default '{}'::jsonb,
  processed_at timestamp with time zone default now() not null
);


