;

CREATE OR REPLACE FUNCTION public.admin_get_users()
 RETURNS TABLE(id uuid, email text, display_name text, role text, is_deleted boolean, status text, disclaimer_age_accepted boolean, disclaimer_financial_accepted boolean, created_at timestamp with time zone, updated_at timestamp with time zone, subscription jsonb, entitlement jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Access denied'; END IF; RETURN QUERY SELECT u.id, u.email, u.display_name, u.role, u.is_deleted, u.status, u.disclaimer_age_accepted, u.disclaimer_financial_accepted, u.created_at, u.updated_at, to_jsonb(s.*) AS subscription, to_jsonb(e.*) AS entitlement FROM public.users u LEFT JOIN public.subscriptions s ON s.user_id = u.id LEFT JOIN public.entitlements e ON e.user_id = u.id ORDER BY u.created_at DESC; END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_manage_user_tier(p_target_user_id uuid, p_new_tier text, p_status text DEFAULT 'active'::text, p_valid_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE v_target_email TEXT; v_admin_email TEXT; v_features JSONB; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Access Denied'; END IF; IF p_new_tier NOT IN ('free', 'standard', 'bigbang', 'admin') THEN RAISE EXCEPTION 'Invalid tier'; END IF; IF p_new_tier = 'free' THEN p_valid_until := NULL; END IF; SELECT email INTO v_target_email FROM public.users WHERE id = p_target_user_id; IF v_target_email IS NULL THEN RAISE EXCEPTION 'Target user does not exist.'; END IF; v_admin_email := auth.jwt() ->> 'email'; v_features := CASE WHEN p_new_tier = 'bigbang' THEN '{"football_predictions": true, "simulations": true, "vip": true}'::jsonb WHEN p_new_tier = 'standard' THEN '{"football_predictions": true, "simulations": false}'::jsonb WHEN p_new_tier = 'admin' THEN '{"football_predictions": true, "simulations": true, "vip": true, "admin": true}'::jsonb ELSE '{"football_predictions": false, "simulations": false}'::jsonb END; UPDATE public.users SET role = p_new_tier, status = p_status, is_deleted = (p_status = 'disabled'), updated_at = now() WHERE id = p_target_user_id; INSERT INTO public.entitlements (user_id, tier, features, valid_until, updated_at) VALUES (p_target_user_id, p_new_tier, v_features, p_valid_until, now()) ON CONFLICT (user_id) DO UPDATE SET tier = EXCLUDED.tier, features = EXCLUDED.features, valid_until = EXCLUDED.valid_until, updated_at = now(); INSERT INTO public.subscriptions (user_id, tier, status, current_period_end, updated_at) VALUES (p_target_user_id, p_new_tier, p_status, p_valid_until, now()) ON CONFLICT (user_id) DO UPDATE SET tier = EXCLUDED.tier, status = EXCLUDED.status, current_period_end = EXCLUDED.current_period_end, updated_at = now(); INSERT INTO public.audit_logs (actor_type, actor_id, action, resource_type, resource_id, details) VALUES ('admin', auth.uid()::text, 'admin_user_tier_allocated', 'users', p_target_user_id::text, jsonb_build_object('actor_email', v_admin_email, 'target_email', v_target_email, 'allocated_tier', p_new_tier, 'status', p_status, 'valid_until', p_valid_until, 'reason', COALESCE(p_reason, 'Admin dashboard allocation'))); RETURN jsonb_build_object('success', true, 'user_id', p_target_user_id, 'email', v_target_email, 'tier', p_new_tier, 'status', p_status, 'valid_until', p_valid_until); END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_record_manual_payment(p_target_user_id uuid, p_tier text, p_amount numeric, p_reference text, p_valid_until timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_admin() then
    raise exception 'Access denied' using errcode = '42501';
  end if;

  update public.users
     set role = p_tier, status = 'active', is_deleted = false, updated_at = now()
   where id = p_target_user_id;

  insert into public.subscriptions (user_id, tier, status, current_period_end, updated_at)
  values (p_target_user_id, p_tier, 'active', p_valid_until, now())
  on conflict (user_id) do update
    set tier = excluded.tier,
        status = 'active',
        current_period_end = excluded.current_period_end,
        updated_at = now();

  insert into public.admin_tasks (task_name, status, metadata)
  values ('MANUAL_PAYMENT_RECORDED', 'COMPLETED', jsonb_build_object(
    'target_user_id', p_target_user_id, 'tier', p_tier, 'amount', p_amount,
    'reference', p_reference, 'valid_until', p_valid_until, 'recorded_by', auth.uid()));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_toggle_league(p_league_id bigint, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE v_caller_role TEXT; BEGIN SELECT role INTO v_caller_role FROM public.users WHERE id = auth.uid(); IF v_caller_role IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Unauthorized: Only admin users can toggle league status'; END IF; UPDATE public.leagues SET is_active = p_is_active, updated_at = NOW() WHERE id = p_league_id; RETURN jsonb_build_object('success', true, 'league_id', p_league_id, 'is_active', p_is_active); END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_toggle_league(target_league_id uuid, is_active_state boolean, reason text DEFAULT 'Operational update'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id UUID;
    v_caller_email TEXT;
    v_old_state BOOLEAN;
    v_league_name TEXT;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION '403 Forbidden: Caller is not an authorized administrator.';
    END IF;

    v_caller_id := auth.uid();
    SELECT email INTO v_caller_email FROM public.users WHERE id = v_caller_id;

    SELECT is_active, name INTO v_old_state, v_league_name
    FROM public.football_leagues
    WHERE id = target_league_id;

    UPDATE public.football_leagues
    SET is_active = is_active_state, updated_at = now()
    WHERE id = target_league_id;

    INSERT INTO public.audit_logs (
        actor_type, actor_id, action, resource_type, resource_id, details
    ) VALUES (
        'admin', v_caller_id::text, 'admin_toggle_league', 'football_leagues', target_league_id::text,
        jsonb_build_object(
            'admin_email', v_caller_email,
            'league_name', v_league_name,
            'previous_state', v_old_state,
            'new_state', is_active_state,
            'reason', reason,
            'timestamp_wat', TO_CHAR(now() AT TIME ZONE 'Africa/Lagos', 'YYYY-MM-DD HH24:MI:SS WAT')
        )
    );

    RETURN jsonb_build_object(
        'status', 'success',
        'league_id', target_league_id,
        'league_name', v_league_name,
        'is_active', is_active_state
    );
END;
$function$
;

