AS $function$ DECLARE v_caller_role TEXT; BEGIN SELECT role INTO v_caller_role FROM public.users WHERE id = auth.uid(); IF v_caller_role IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Unauthorized: Only admin users can update user roles'; END IF; IF p_new_role NOT IN ('user', 'admin') THEN RAISE EXCEPTION 'Invalid role specified: %', p_new_role; END IF; UPDATE public.users SET role = p_new_role, updated_at = NOW() WHERE id = p_target_user_id; RETURN jsonb_build_object('success', true, 'user_id', p_target_user_id, 'new_role', p_new_role); END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_update_user_role(target_user_id uuid, new_role text, reason text DEFAULT 'Administrative review'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id UUID;
    v_caller_email TEXT;
    v_old_role TEXT;
    v_target_email TEXT;
    v_audit_id UUID;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION '403 Forbidden: Caller is not an authorized administrator.';
    END IF;

    IF new_role NOT IN ('free', 'standard', 'bigbang', 'admin') THEN
        RAISE EXCEPTION 'Invalid role: %', new_role;
    END IF;

    v_caller_id := auth.uid();
    SELECT email INTO v_caller_email FROM public.users WHERE id = v_caller_id;

    SELECT role, email INTO v_old_role, v_target_email
    FROM public.users
    WHERE id = target_user_id;

    IF v_old_role IS NULL THEN
        RAISE EXCEPTION 'Target user not found.';
    END IF;

    -- Update user role in public.users
    UPDATE public.users
    SET role = new_role, updated_at = now()
    WHERE id = target_user_id;

    -- Update public.entitlements accordingly
    UPDATE public.entitlements
    SET tier = CASE WHEN new_role = 'admin' THEN 'bigbang' ELSE new_role END,
        features = CASE
            WHEN new_role IN ('standard', 'bigbang', 'admin') THEN '{"football_predictions": true}'::jsonb
            ELSE '{"football_predictions": false}'::jsonb
        END,
        updated_at = now()
    WHERE user_id = target_user_id;

    -- Update subscription record
    UPDATE public.subscriptions
    SET tier = CASE WHEN new_role = 'admin' THEN 'bigbang' ELSE new_role END,
        updated_at = now()
    WHERE user_id = target_user_id;

    -- Cryptographic Audit Record
    INSERT INTO public.audit_logs (
        actor_type, actor_id, action, resource_type, resource_id, details
    ) VALUES (
        'admin', v_caller_id::text, 'admin_update_user_role', 'users', target_user_id::text,
        jsonb_build_object(
            'admin_email', v_caller_email,
            'target_user_id', target_user_id,
            'target_email', v_target_email,
            'previous_state', v_old_role,
            'new_state', new_role,
            'reason', reason,
            'timestamp_wat', TO_CHAR(now() AT TIME ZONE 'Africa/Lagos', 'YYYY-MM-DD HH24:MI:SS WAT')
        )
    ) RETURNING id INTO v_audit_id;

    RETURN jsonb_build_object(
        'status', 'success',
        'target_user_id', target_user_id,
        'previous_role', v_old_role,
        'new_role', new_role,
        'reason', reason,
        'audit_id', v_audit_id
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_away_win_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ BEGIN IF OLD.settlement_status IN ('won', 'lost', 'void', 'voided') AND OLD.settled_at < NOW() - INTERVAL '48 hours' THEN RAISE EXCEPTION 'Settled away win prediction is permanently immutable after 48 hours.'; END IF; RETURN NEW; END; $function$
