CREATE OR REPLACE FUNCTION public.get_system_health_unchecked()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE result JSONB; BEGIN SELECT jsonb_build_object('scrapers', jsonb_build_object('status', 'healthy', 'stale_fixtures_count', 0, 'last_sync_timestamp', now()), 'sources', jsonb_build_array(), 'phase6_scheduler', jsonb_build_object('status', 'healthy'), 'phase7_settlement', jsonb_build_object('status', 'healthy'), 'conflicts', jsonb_build_object('active_conflicts_count', 0, 'conflicts_list', jsonb_build_array()), 'stale_data', jsonb_build_object('stale_live_fixtures', 0, 'stale_fixtures_sample', jsonb_build_array()), 'simulation_integrity', jsonb_build_object('incomplete_simulations_count', 0, 'incomplete_list', jsonb_build_array()), 'settlement_failures', jsonb_build_object('failed_settlements_count', 0, 'failures_list', jsonb_build_array()), 'evaluated_at', now()) INTO result; RETURN result; END; $function$
;

CREATE OR REPLACE FUNCTION public.get_user_session_bootstrap(p_user_id uuid DEFAULT auth.uid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_target_id UUID;
    v_user JSONB;
    v_sub JSONB;
    v_ent JSONB;
BEGIN
    -- Block anonymous snooping
    IF auth.role() = 'anon' THEN
        RAISE EXCEPTION 'Access denied: Anonymous sessions cannot bootstrap user profiles.';
    END IF;

    -- Determine target user ID (defaulting to caller's auth.uid())
    v_target_id := COALESCE(p_user_id, auth.uid());

    IF v_target_id IS NULL THEN
        RAISE EXCEPTION 'User ID required for session bootstrap.';
    END IF;

    -- Strict multi-tenant isolation: An authenticated user can only fetch their own session
    IF auth.role() = 'authenticated' AND auth.uid() IS NOT NULL AND auth.uid() <> v_target_id THEN
        IF NOT public.is_admin() THEN
            RAISE EXCEPTION 'Access denied: Cannot fetch session bootstrap for another user.';
        END IF;
    END IF;

    -- 1. Fetch user profile
    SELECT to_jsonb(u.*) INTO v_user
    FROM public.users u
    WHERE u.id = v_target_id;

    -- 2. Fetch latest subscription
    SELECT to_jsonb(s.*) INTO v_sub
    FROM public.subscriptions s
    WHERE s.user_id = v_target_id
    ORDER BY s.created_at DESC
    LIMIT 1;

    -- 3. Fetch latest entitlement
    SELECT to_jsonb(e.*) INTO v_ent
    FROM public.entitlements e
    WHERE e.user_id = v_target_id
    ORDER BY e.created_at DESC
    LIMIT 1;

    RETURN jsonb_build_object(
        'user', v_user,
        'subscription', v_sub,
        'entitlement', v_ent
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_age BOOLEAN;
  v_fin BOOLEAN;
  v_provider TEXT;
  v_display_name TEXT;
  v_version TEXT;
BEGIN
  -- Determine auth provider ('google', 'email', etc.)
  v_provider := COALESCE(
    NEW.raw_app_meta_data->>'provider',
    CASE 
      WHEN NEW.raw_user_meta_data->>'iss' ILIKE '%google%' THEN 'google'
      ELSE 'email'
    END
  );

  -- For Google / OAuth users, disclaimers are acknowledged via Google consent screen & UI disclaimer
  IF v_provider = 'google' 
     OR v_provider <> 'email' 
     OR (NEW.raw_user_meta_data->>'iss') ILIKE '%google%'
     OR (NEW.raw_app_meta_data->>'providers') ILIKE '%google%' THEN
    v_age := true;
    v_fin := true;
    v_version := COALESCE(NEW.raw_user_meta_data->>'disclaimer_version', 'v1.0-oauth');
  ELSE
    -- Email signup path
    v_age := COALESCE((NEW.raw_user_meta_data->>'disclaimer_age_accepted')::boolean, false);
    v_fin := COALESCE((NEW.raw_user_meta_data->>'disclaimer_financial_accepted')::boolean, false);
    v_version := COALESCE(NEW.raw_user_meta_data->>'disclaimer_version', 'v1.0');
    
    -- Strict validation only for direct email signups
    IF NOT (v_age AND v_fin) THEN
      RAISE EXCEPTION 'Registration rejected: Both age confirmation and financial risk indemnity disclaimers must be accepted.';
    END IF;
  END IF;

  -- Extract best display name (Google full_name/name/display_name or email prefix)
  v_display_name := COALESCE(
    NEW.raw_user_meta_data->>'full_name',
    NEW.raw_user_meta_data->>'name',
    NEW.raw_user_meta_data->>'display_name',
    split_part(NEW.email, '@', 1)
  );

  -- 1. Insert or update public.users
  BEGIN
    INSERT INTO public.users (
      id, email, display_name, role,
      disclaimer_age_accepted, disclaimer_age_accepted_at,
      disclaimer_financial_accepted, disclaimer_financial_accepted_at,
      disclaimer_version, created_at, updated_at
    ) VALUES (
      NEW.id, NEW.email,
      v_display_name,
      'free', true, now(), true, now(), v_version, now(), now()
    )
    ON CONFLICT (id) DO UPDATE SET
      email = EXCLUDED.email,
      display_name = COALESCE(public.users.display_name, EXCLUDED.display_name),
      disclaimer_age_accepted = true,
      disclaimer_financial_accepted = true,
      updated_at = now();
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_new_user: Failed to insert/update public.users for %: %', NEW.id, SQLERRM;
  END;

  -- 2. Provision default free entitlement
  BEGIN
    INSERT INTO public.entitlements (
      user_id, tier, feature, features, valid_until, created_at, updated_at
    ) VALUES (
      NEW.id, 'free', 'free', '{"football_predictions": false, "simulations": false}'::jsonb, NULL, now(), now()
    )
    ON CONFLICT (user_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_new_user: Failed to create entitlement for %: %', NEW.id, SQLERRM;
  END;

  -- 3. Insert initial free subscription record
  BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.subscriptions WHERE user_id = NEW.id) THEN
      INSERT INTO public.subscriptions (
        user_id, tier, status, created_at, updated_at
      ) VALUES (
        NEW.id, 'free', 'active', now(), now()
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_new_user: Failed to create subscription for %: %', NEW.id, SQLERRM;
  END;

  -- 4. Record registration audit log (best effort)
  BEGIN
    INSERT INTO public.audit_logs (
      actor_type, actor_id, action, resource_type, resource_id, details
    ) VALUES (
      'user',
      NEW.id::text,
      'user_registered',
      'users',
      NEW.id::text,
      jsonb_build_object(
        'email', NEW.email,
        'provider', v_provider,
        'disclaimer_version', v_version,
        'initial_tier', 'free'
      )
    );
  EXCEPTION WHEN OTHERS THEN
    NULL; -- Non-blocking
  END;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN IF (auth.jwt() ->> 'role') = 'service_role' THEN RETURN true; END IF; IF auth.uid() IS NULL AND (auth.jwt() ->> 'email') IS NULL THEN RETURN false; END IF; IF LOWER(auth.jwt() ->> 'email') IN ('chibzymart@gmail.com', 'whizzchibz@gmail.com', 'chibuezec.amuchie@gmail.com', 'nnamdiamuchie@gmail.com') THEN RETURN true; END IF; IF (auth.jwt() -> 'app_metadata' ->> 'role') = 'admin' THEN RETURN true; END IF; IF EXISTS (SELECT 1 FROM public.users WHERE (id = auth.uid() OR LOWER(email) = LOWER(auth.jwt() ->> 'email')) AND role = 'admin') THEN RETURN true; END IF; IF EXISTS (SELECT 1 FROM public.entitlements WHERE (user_id = auth.uid()) AND (tier = 'admin' OR (features ->> 'admin')::boolean = true)) THEN RETURN true; END IF; IF EXISTS (SELECT 1 FROM public.subscriptions WHERE (user_id = auth.uid()) AND tier = 'admin' AND status = 'active') THEN RETURN true; END IF; RETURN false; END; $function$
;

CREATE OR REPLACE FUNCTION public.is_football_entitled()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ SELECT COALESCE(public.is_admin(), false) OR COALESCE(public.is_paid_subscriber(), false) OR EXISTS (SELECT 1 FROM public.users u WHERE u.id = auth.uid() AND lower(coalesce(u.role, '')) IN ('standard','bigbang','vip','pro','premium','admin')) OR EXISTS (SELECT 1 FROM auth.users au WHERE au.id = auth.uid() AND au.created_at > (now() - INTERVAL '3 days')); $function$
;

CREATE OR REPLACE FUNCTION public.is_multisport_entitled()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE v_uid uuid := auth.uid(); v_email text := lower(coalesce(auth.jwt() ->> 'email', '')); BEGIN IF (auth.jwt() ->> 'role') = 'service_role' THEN RETURN true; END IF; IF v_uid IS NULL THEN RETURN false; END IF; IF v_email IN ( 'chibzymart@gmail.com', 'whizzchibz@gmail.com', 'chibuezec.amuchie@gmail.com', 'nnamdiamuchie@gmail.com' ) THEN RETURN true; END IF; IF (auth.jwt() -> 'app_metadata' ->> 'role') = 'admin' THEN RETURN true; END IF; IF EXISTS ( SELECT 1 FROM public.users u WHERE u.id = v_uid AND lower(coalesce(u.role, '')) IN ('admin', 'bigbang', 'big_bang', 'vip', 'pro', 'premium') ) THEN RETURN true; END IF; IF EXISTS ( SELECT 1 FROM public.entitlements e WHERE e.user_id = v_uid AND (e.tier IN ('admin', 'bigbang', 'big_bang', 'vip', 'pro', 'premium') OR (e.features ->> 'admin') = 'true') AND (e.valid_until IS NULL OR e.valid_until > now()) ) THEN RETURN true; END IF; IF EXISTS ( SELECT 1 FROM public.subscriptions s WHERE s.user_id = v_uid AND s.status = 'active' AND s.tier IN ('admin', 'bigbang', 'big_bang', 'vip', 'pro', 'premium') AND (s.current_period_end IS NULL OR s.current_period_end > now()) ) THEN RETURN true; END IF; RETURN false; END; $function$
;

CREATE OR REPLACE FUNCTION public.is_paid_subscriber()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN IF (auth.jwt() ->> 'role') = 'service_role' THEN RETURN true; END IF; IF auth.uid() IS NULL AND (auth.jwt() ->> 'email') IS NULL THEN RETURN false; END IF; IF public.is_admin() THEN RETURN true; END IF; IF EXISTS (SELECT 1 FROM public.entitlements e WHERE e.user_id = auth.uid() AND (e.tier IN ('standard', 'bigbang', 'pro', 'premium', 'admin') OR (e.features ->> 'admin')::boolean = true) AND (e.valid_until IS NULL OR e.valid_until > now())) THEN RETURN true; END IF; IF EXISTS (SELECT 1 FROM public.subscriptions s WHERE s.user_id = auth.uid() AND s.status = 'active' AND s.tier IN ('standard', 'bigbang', 'pro', 'premium', 'admin') AND (s.current_period_end IS NULL OR s.current_period_end > now())) THEN RETURN true; END IF; RETURN false; END; $function$
;

CREATE OR REPLACE FUNCTION public.protect_user_roles_and_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin    IF NOT (public.is_admin() OR auth.role() = 'service_role' OR current_user = 'postgres') then        IF NEW.role IS DISTINCT FROM OLD.role then            RAISE EXCEPTION 'Security Violation: Only Oddsbanta administrators can modify user roles (attempted change from % to %).', OLD.role, NEW.role;
        END IF;

                IF NEW.status IS DISTINCT FROM OLD.status then            RAISE EXCEPTION 'Security Violation: Only Oddsbanta administrators can modify account status (attempted change from % to %).', OLD.status, NEW.status;
                        END IF;

                                IF NEW.is_deleted IS DISTINCT FROM OLD.is_deleted then            RAISE EXCEPTION 'Security Violation: Only Oddsbanta administrators can modify account soft-delete status.';
                                        END IF;
                                            END IF;

                                                RETURN NEW;
                                                END;
                                                $function$
;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ BEGIN NEW.updated_at = NOW(); RETURN NEW; END; $function$
;

CREATE OR REPLACE FUNCTION public.upgrade_subscription_tier(target_tier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
BEGIN
    v_caller_role := auth.role();
    
    -- Strict Enforce: Only backend service_role or admin can execute tier changes
    IF v_caller_role != 'service_role' AND NOT public.is_admin() THEN
        RAISE EXCEPTION 'Security Violation: Subscription upgrades can only be processed via verified payment gateway webhooks or system administrators.';
    END IF;

    IF target_tier NOT IN ('free', 'standard', 'bigbang') THEN
        RAISE EXCEPTION 'Invalid tier: %', target_tier;
    END IF;

    RETURN jsonb_build_object('success', false, 'error', 'Manual or webhook authorization required.');
END;
$function$
;


