create or replace view public.away_win_predictions_paywall as
 SELECT id,
    fixture_id,
    prediction,
    market,
    probability,
    confidence_category,
    counter_tier,
    away_counter_efficiency,
    away_clean_sheet_prob,
    settlement_status,
    settlement_notes,
    settled_at,
    actual_score,
    publication_status,
    target_kickoff_at,
    created_at,
    updated_at,
    confidence_category = 'LOCKED'::text OR publication_status = 'draft'::text AS is_locked
   FROM away_win_predictions;

create or replace view public.basketball_predictions_paywall with (security_invoker=true) as
 SELECT p.id,
    p.fixture_id,
    p.market,
        CASE
            WHEN is_multisport_entitled() THEN p.prediction
            WHEN is_multisport_entitled() THEN p.prediction
            WHEN p.settlement_status = ANY (ARRAY['won'::text, 'lost'::text, 'void'::text]) THEN p.prediction
            WHEN f.status = ANY (ARRAY['finished'::text, 'cancelled'::text, 'postponed'::text]) THEN p.prediction
            ELSE 'LOCKED'::text
        END AS prediction,
        CASE
            WHEN is_multisport_entitled() THEN p.probability
            WHEN is_multisport_entitled() THEN p.probability
            WHEN p.settlement_status = ANY (ARRAY['won'::text, 'lost'::text, 'void'::text]) THEN p.probability
            WHEN f.status = ANY (ARRAY['finished'::text, 'cancelled'::text, 'postponed'::text]) THEN p.probability
            ELSE NULL::numeric
        END AS probability,
        CASE
            WHEN is_multisport_entitled() THEN p.confidence_category
            WHEN is_multisport_entitled() THEN p.confidence_category
            WHEN p.settlement_status = ANY (ARRAY['won'::text, 'lost'::text, 'void'::text]) THEN p.confidence_category
            WHEN f.status = ANY (ARRAY['finished'::text, 'cancelled'::text, 'postponed'::text]) THEN p.confidence_category
            ELSE 'LOCKED'::text
        END AS confidence_category,
        CASE
            WHEN is_multisport_entitled() THEN p.secondary_predictions
            WHEN is_multisport_entitled() THEN p.secondary_predictions
            WHEN p.settlement_status = ANY (ARRAY['won'::text, 'lost'::text, 'void'::text]) THEN p.secondary_predictions
            WHEN f.status = ANY (ARRAY['finished'::text, 'cancelled'::text, 'postponed'::text]) THEN p.secondary_predictions
            ELSE '[]'::jsonb
        END AS secondary_predictions,
        CASE
            WHEN is_multisport_entitled() THEN p.metadata
            WHEN is_multisport_entitled() THEN p.metadata
            WHEN p.settlement_status = ANY (ARRAY['won'::text, 'lost'::text, 'void'::text]) THEN p.metadata
            WHEN f.status = ANY (ARRAY['finished'::text, 'cancelled'::text, 'postponed'::text]) THEN p.metadata
            ELSE '{}'::jsonb
        END AS metadata,
    p.simulations_count,
    p.simulated_home_score,
    p.simulated_away_score,
    p.edge_percentage,
    p.fair_odds,
    p.market_odds,
    p.tier_required,
    p.publication_status,
    p.target_kickoff_at,
    p.settlement_status,
    p.settlement_notes,
    p.settled_at,
    p.actual_result,
    p.created_at,
    p.updated_at,
        CASE
            WHEN is_multisport_entitled() THEN false
            WHEN is_multisport_entitled() THEN false
            WHEN p.settlement_status = ANY (ARRAY['won'::text, 'lost'::text, 'void'::text]) THEN false
            WHEN f.status = ANY (ARRAY['finished'::text, 'cancelled'::text, 'postponed'::text]) THEN false
            ELSE true
        END AS is_locked
   FROM basketball_predictions p
     JOIN basketball_fixtures f ON f.id = p.fixture_id
  WHERE p.publication_status = 'published'::text;

