create or replace view public.football_prediction_queue with (security_invoker=true) as
 SELECT f.id,
    f.canonical_key,
    f.target_kickoff_at,
    f.status,
    f.queue_day,
    f.in_prediction_queue,
    f.home_score,
    f.away_score,
    f.match_minute,
    f.period,
    f.half_time_home_score,
    f.half_time_away_score,
    f.corners_home,
    f.corners_away,
    f.last_synced_at,
    f.postponed_at,
    f.cancelled_at,
    f.created_at,
    f.updated_at,
    l.id AS league_id,
    l.name AS league_name,
    l.code AS league_code,
    l.country AS league_country,
    ht.id AS home_team_id,
    ht.name AS home_team_name,
    at.id AS away_team_id,
    at.name AS away_team_name
   FROM football_fixtures f
     JOIN football_leagues l ON f.league_id = l.id
     JOIN football_teams ht ON f.home_team_id = ht.id
     JOIN football_teams at ON f.away_team_id = at.id
  WHERE f.in_prediction_queue = true
  ORDER BY f.target_kickoff_at;

