            WHEN p.settlement_status = ANY (ARRAY['won'::text, 'lost'::text, 'void'::text]) THEN p.metadata
            WHEN f.status = ANY (ARRAY['finished'::text, 'retired'::text, 'walkover'::text]) THEN p.metadata
            ELSE '{}'::jsonb
        END AS metadata,
    p.simulations_count,
    p.tier_required,
    p.publication_status,
    p.target_kickoff_at,
    p.settlement_status,
    p.settlement_notes,
    p.settled_at,
    p.actual_result,
    p.created_at,
    p.updated_at,
        CASE
            WHEN is_multisport_entitled() THEN false
            WHEN is_multisport_entitled() THEN false
            WHEN p.settlement_status = ANY (ARRAY['won'::text, 'lost'::text, 'void'::text]) THEN false
            WHEN f.status = ANY (ARRAY['finished'::text, 'retired'::text, 'walkover'::text]) THEN false
            ELSE true
        END AS is_locked
   FROM tennis_predictions p
     JOIN tennis_fixtures f ON f.id = p.fixture_id
  WHERE p.publication_status = 'published'::text;


