CREATE TRIGGER trg_enforce_away_win_immutability BEFORE DELETE OR UPDATE ON public.away_win_predictions FOR EACH ROW EXECUTE FUNCTION enforce_away_win_immutability();
CREATE TRIGGER trg_enforce_corner_immutability BEFORE DELETE OR UPDATE ON public.corner_predictions FOR EACH ROW EXECUTE FUNCTION enforce_corner_immutability();
CREATE TRIGGER trg_enforce_draw_immutability BEFORE DELETE OR UPDATE ON public.draw_predictions FOR EACH ROW EXECUTE FUNCTION enforce_draw_immutability();
CREATE TRIGGER trg_enforce_home_win_immutability BEFORE DELETE OR UPDATE ON public.home_win_predictions FOR EACH ROW EXECUTE FUNCTION enforce_home_win_immutability();
CREATE TRIGGER trg_protect_user_roles_and_status BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION protect_user_roles_and_status();
